private suspend fun restoreBrokerConnection(backend: AnalystBackendClient, accessToken: String,
    legacyTInvestStore: TInvestTokenStore): Pair<Boolean, BrokerConnectionState> {
        val status = withContext(Dispatchers.IO) {
            backend.fetchTInvestStatus(accessToken)
        }

        var connected = (status as? BackendResult.Success)?.value ?: false
        if (status is BackendResult.Success && !connected) {
            val legacyToken = withContext(Dispatchers.IO) {
                legacyTInvestStore.load()
            }
            if (!legacyToken.isNullOrBlank()) {
                val migration = withContext(Dispatchers.IO) {
                    backend.saveTInvestToken(
                        accessToken = accessToken,
                        token = legacyToken,
                    )
                }
                if (migration is BackendResult.Success) {
                    withContext(Dispatchers.IO) {
                        legacyTInvestStore.clear()
                    }
                    connected = true
                }
            }
        }
        return connected to if (connected) BrokerConnectionState.Connected else if (status is BackendResult.Failure) BrokerConnectionState.Unknown else BrokerConnectionState.Missing
}

private fun workspaceTransition(initialState: AppScreen, targetState: AppScreen, motion: Boolean): ContentTransform {
            val roots = setOf(AppScreen.Home, AppScreen.Portfolio, AppScreen.Recommendations, AppScreen.Risk, AppScreen.Profile)
            val duration = if (motion) 180 else 0
            return if (initialState in roots && targetState in roots) fadeIn(tween(duration)) togetherWith fadeOut(tween(duration))
            else {
                val direction = if (targetState in roots) -1 else 1
                (slideInHorizontally(tween(duration)) { it / 8 * direction } + fadeIn(tween(duration))) togetherWith
                    (slideOutHorizontally(tween(duration)) { -it / 8 * direction } + fadeOut(tween(duration)))
            }
}

private suspend fun exchangeTelegramSession(
    backend: AnalystBackendClient,
    sessionStore: AuthSessionStore,
    context: android.content.Context,
    code: String,
): AuthUiState = SessionTransitions.run {
    when (val result = backend.exchangeTelegramCode(code)) {
        is BackendResult.Success -> {
            val saved =
                withContext(Dispatchers.IO) {
                    runCatching {
                        sessionStore.save(result.value)
                        EncryptedWorkspaceStore(context).activateUser(result.value.user.telegramId)
                    }
                        .isSuccess
                }
            if (saved) AuthUiState.SignedIn(result.value.accessToken, result.value.user)
            else
                AuthUiState.SignedOut(
                    errorMessage = "Не удалось сохранить вход на устройстве. Попробуйте ещё раз."
                )
        }
        is BackendResult.Failure -> AuthUiState.SignedOut(errorMessage = result.message)
    }
}

private suspend fun restoreAnalystSession(
    backend: AnalystBackendClient,
    sessionStore: AuthSessionStore,
    context: android.content.Context,
): AuthUiState = SessionTransitions.run {
    val storedToken =
        withContext(Dispatchers.IO) { sessionStore.loadAccessToken() }
            ?: return@run AuthUiState.SignedOut()
    when (val result = backend.fetchMe(storedToken)) {
        is BackendResult.Success -> {
            withContext(Dispatchers.IO) {
                EncryptedWorkspaceStore(context).activateUser(result.value.telegramId)
            }
            AuthUiState.SignedIn(storedToken, result.value)
        }
        is BackendResult.Failure -> {
            if (result.retryable) {
                val cachedUser = withContext(Dispatchers.IO) { sessionStore.loadCachedUser() }
                if (cachedUser != null) AuthUiState.SignedIn(storedToken, cachedUser)
                else AuthUiState.SignedOut(errorMessage = result.message)
            } else {
                withContext(Dispatchers.IO) { sessionStore.clear() }
                AuthUiState.SignedOut()
            }
        }
    }
}

package ru.omnicio.app.data.workspace

import java.net.URI

/** Keep newly added controller reads on the same authenticated application origin. */
internal object WorkspaceEndpointPolicy {
    private val automationPaths = setOf(
        "/automation/status",
        "/automation/preferences",
        "/automation/decisions",
    )

    fun permits(path: String): Boolean {
        val allowed = path == "/workspace" || path.startsWith("/workspace/") ||
            path.startsWith("/workspace?") || path == "/analysis/profile" || path in automationPaths
        if (!allowed || '#' in path) return false
        return try {
            val uri = URI(path)
            uri.scheme == null && uri.authority == null && uri.path?.contains("..") == false
        } catch (_: Exception) {
            false
        }
    }
}

