                                title = "Моя стратегия",
                                subtitle = "Цель, отбор, доли и доход",
                                symbol = SpectrumSymbol.Goal,
                                onClick = { openWorkspace(WorkspaceRoute.Strategies) },
                            )
                        }
                    } else {
                        accountPositionRows(snapshot, onOpenAccount, onPositionClick)
                    }
