package ru.omnicio.app.ui.spatial

import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.luminance
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test
import ru.omnicio.app.ui.spectrum.spectrumPalette
import ru.omnicio.app.ui.workspace.AccentStyle

class SpatialColorsTest {
    private fun contrast(a: Color, b: Color): Double =
        (maxOf(a.luminance(), b.luminance()).toDouble() + .05) /
            (minOf(a.luminance(), b.luminance()).toDouble() + .05)

    @Test
    fun theActualCheckedThumbUsesItsPairedInkInBothModesAndEveryAccent() {
        for (dark in listOf(false, true)) for (accent in AccentStyle.entries) {
            val palette = spectrumPalette(dark, accent)
            val checked = spatialToggleColors(palette, checked = true, enabled = true)
            assertEquals(palette.colors.primary, checked.track)
            assertEquals(palette.colors.onPrimary, checked.thumb)
            assertTrue(contrast(checked.thumb, checked.track) >= 3.0)
            val unchecked = spatialToggleColors(palette, checked = false, enabled = true)
            assertTrue(contrast(unchecked.thumb, unchecked.track) >= 3.0)
            assertTrue(contrast(unchecked.outline, palette.card) >= 3.0)
        }
    }

    @Test
    fun monochromeArtworkHonorsAnyActualForegroundRatherThanAWhiteSentinel() {
        for (dark in listOf(false, true)) for (accent in AccentStyle.entries) {
            val palette = spectrumPalette(dark, accent)
            for (ink in listOf(palette.colors.onPrimary, palette.colors.onPrimaryContainer, palette.colors.onSurface)) {
                val actual = flatArtworkColors(palette, ink, SpatialColorMode.Monochrome, SpatialState.Idle)
                assertEquals(listOf(ink, ink, ink, ink), listOf(actual.teal, actual.violet, actual.amber, actual.rose))
                assertEquals(ink, actual.ink)
            }
            val artwork = flatArtworkColors(palette, palette.cyan, SpatialColorMode.Decorative, SpatialState.Idle)
            assertEquals(4, listOf(artwork.teal, artwork.violet, artwork.amber, artwork.rose).distinct().size)
        }
    }

    @Test
    fun disablingArtworkRemovesEverySaturatedSupportInk() {
        for (dark in listOf(false, true)) for (accent in AccentStyle.entries) for (mode in SpatialColorMode.entries) {
            val palette = spectrumPalette(dark, accent)
            val actual = flatArtworkColors(palette, palette.cyan, mode, SpatialState.Disabled)
            assertEquals(setOf(palette.semantic.disabledInk),
                setOf(actual.ink, actual.teal, actual.violet, actual.amber, actual.rose))
            val control = spatialToggleColors(palette, checked = true, enabled = false)
            assertEquals(palette.semantic.disabledContainer, control.track)
            assertTrue(contrast(control.thumb, control.track) >= 3.0)
        }
    }

    @Test
    fun neutralPressedCardsStillSupportSecondaryTextAndFocusHasAVisibleEdge() {
        for (dark in listOf(false, true)) for (accent in AccentStyle.entries) {
            val palette = spectrumPalette(dark, accent)
            val c = palette.colors
            for (fill in listOf(c.background, c.surface, c.surfaceVariant, c.surfaceBright, c.surfaceDim,
                c.surfaceContainerLowest, c.surfaceContainerLow, c.surfaceContainer, c.surfaceContainerHigh,
                c.surfaceContainerHighest)) {
                val pressed = spatialSurfaceColors(palette, fill, SpatialState.Pressed, true, false, false)
                assertTrue("Secondary text lost contrast under a real pressed state", contrast(c.onSurfaceVariant, pressed.fill) >= 4.5)
            }
            val focused = spatialSurfaceColors(palette, c.primary, SpatialState.Selected, true, false, false)
            assertEquals(c.onPrimary, focused.border)
            assertTrue(contrast(focused.border, focused.fill) >= 3.0)
            val disabled = spatialSurfaceColors(palette, c.primary, SpatialState.Disabled, true, false, false)
            assertEquals(palette.semantic.disabledInk, disabled.foreground)
            assertTrue(contrast(disabled.foreground, disabled.fill) >= 3.0)
        }
    }

    @Test
    fun historyColorIsResolvedForEveryObservationWithoutMovingNullOrNegativeSlots() {
        val observations = listOf(120.0, 160.0, 0.0, null, -20.0, 170.0)
        for (dark in listOf(false, true)) for (accent in AccentStyle.entries) {
            val palette = spectrumPalette(dark, accent)
            val actual = historyBarColors(palette, observations)
            assertEquals(observations.size, actual.size)
            assertEquals(listOf(palette.blue, palette.blue, palette.blue, palette.blue, palette.rose, palette.blue), actual)
        }
    }

    @Test
    fun semanticWarningsAndErrorsRemainDistinctWhileExplicitCallerInkWins() {
        for (dark in listOf(false, true)) {
            val palette = spectrumPalette(dark)
            assertEquals(palette.amber, spatialIconInk(palette, "warning", Color.Unspecified, SpatialState.Attention))
            assertEquals(palette.rose, spatialIconInk(palette, "error", Color.Unspecified, SpatialState.Attention))
            assertEquals(palette.emerald, spatialIconInk(palette, "check", Color.Unspecified, SpatialState.Success))
            assertEquals(palette.colors.onPrimary,
                spatialIconInk(palette, "warning", palette.colors.onPrimary, SpatialState.Attention))
        }
    }

    @Test
    fun actualBadgeAndMetricContainersResolveReadablePairedForeground() {
        for (dark in listOf(false, true)) for (accent in AccentStyle.entries) {
            val palette = spectrumPalette(dark, accent)
            for (color in listOf(palette.cyan, palette.blue, palette.violet, palette.rose, palette.emerald, palette.amber)) {
                val fill = palette.containerFor(color)
                val ink = palette.foregroundFor(fill)
                assertTrue("Actual component container lost its foreground pair", contrast(ink, fill) >= 4.5)
            }
        }
    }
}

package ru.omnicio.app.ui.theme

import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.luminance
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test
import ru.omnicio.app.ui.workspace.AccentStyle

class AnalystColorsTest {
    private fun contrast(a: Color, b: Color): Double {
        val high = maxOf(a.luminance(), b.luminance()).toDouble()
        val low = minOf(a.luminance(), b.luminance()).toDouble()
        return (high + .05) / (low + .05)
    }

    private fun readable(ink: Color, fill: Color, threshold: Double = 4.5) {
        assertEquals("Contrast is evaluated for opaque production tokens", 1f, ink.alpha, 0f)
        assertEquals("Contrast is evaluated for opaque production tokens", 1f, fill.alpha, 0f)
        assertTrue("Actual pair $ink on $fill has contrast ${contrast(ink, fill)}", contrast(ink, fill) >= threshold)
    }

    @Test
    fun everyActionFamilyKeepsPairedMaterialAndSemanticContentReadable() {
        for (dark in listOf(false, true)) for (accent in AccentStyle.entries) {
            val actual = analystColors(dark, accent)
            val c = actual.material
            val s = actual.semantic
            val pairs = listOf(c.onPrimary to c.primary, c.onPrimaryContainer to c.primaryContainer,
                c.onSecondary to c.secondary, c.onSecondaryContainer to c.secondaryContainer,
                c.onTertiary to c.tertiary, c.onTertiaryContainer to c.tertiaryContainer,
                c.onError to c.error, c.onErrorContainer to c.errorContainer,
                c.onBackground to c.background, c.inverseOnSurface to c.inverseSurface,
                s.onSuccess to s.success, s.onSuccessContainer to s.successContainer,
                s.onWarning to s.warning, s.onWarningContainer to s.warningContainer,
                s.onInfo to s.info, s.onInfoContainer to s.infoContainer)
            pairs.forEach { (ink, fill) -> readable(ink, fill) }
            readable(c.onPrimary, analystPressedColor(c.primary, c.onPrimary))
            readable(c.onSurface, c.primaryContainer)
        }
    }

    @Test
    fun surfaceHierarchyKeepsSecondaryTextAndMeaningfulOutlinesReadable() {
        for (dark in listOf(false, true)) for (accent in AccentStyle.entries) {
            val c = analystColors(dark, accent).material
            val surfaces = listOf(c.background, c.surface, c.surfaceVariant, c.surfaceBright, c.surfaceDim,
                c.surfaceContainerLowest, c.surfaceContainerLow, c.surfaceContainer, c.surfaceContainerHigh,
                c.surfaceContainerHighest)
            for (surface in surfaces) {
                readable(c.onSurface, surface)
                readable(c.onSurfaceVariant, surface)
                readable(c.outline, surface, 3.0)
            }
        }
    }

    @Test
    fun fixedPrimaryColorsRemainStableAcrossModesForEveryUserAccent() {
        for (accent in AccentStyle.entries) {
            val light = analystColors(false, accent).material
            val dark = analystColors(true, accent).material
            assertEquals(light.primaryFixed, dark.primaryFixed)
            assertEquals(light.primaryFixedDim, dark.primaryFixedDim)
            assertEquals(light.onPrimaryFixed, dark.onPrimaryFixed)
            assertEquals(light.onPrimaryFixedVariant, dark.onPrimaryFixedVariant)
            for (c in listOf(light, dark)) {
                for (fill in listOf(c.primaryFixed, c.primaryFixedDim)) {
                    readable(c.onPrimaryFixed, fill)
                    readable(c.onPrimaryFixedVariant, fill)
                }
                for (fill in listOf(c.secondaryFixed, c.secondaryFixedDim)) {
                    readable(c.onSecondaryFixed, fill)
                    readable(c.onSecondaryFixedVariant, fill)
                }
                for (fill in listOf(c.tertiaryFixed, c.tertiaryFixedDim)) {
                    readable(c.onTertiaryFixed, fill)
                    readable(c.onTertiaryFixedVariant, fill)
                }
            }
            assertEquals(dark.primary, light.inversePrimary)
            assertEquals(light.primary, dark.inversePrimary)
        }
    }

    @Test
    fun anAccentCannotRecolorFinancialCategoriesOrSuccessWarningError() {
        assertEquals(listOf("AURORA", "OCEAN", "IRIS"), AccentStyle.entries.map { it.name })
        for (dark in listOf(false, true)) {
            val original = analystColors(dark, AccentStyle.AURORA)
            assertEquals(6, original.chartSeries.distinct().size)
            for (accent in AccentStyle.entries) {
                val actual = analystColors(dark, accent)
                assertEquals(original.chartSeries, actual.chartSeries)
                assertEquals(original.semantic, actual.semantic)
                assertEquals(original.material.error, actual.material.error)
                assertEquals(actual.material.primary, actual.material.surfaceTint)
                actual.chartSeries.forEach { readable(it, actual.material.surface, 3.0) }
            }
            assertEquals(original, analystColors(dark, AccentStyle.OCEAN))
            assertEquals(original, analystColors(dark, AccentStyle.IRIS))
        }
    }

    @Test
    fun unavailableCalendarDatesStayReadableOnOrdinarySelectedAndRangeSurfaces() {
        for (dark in listOf(false, true)) for (accent in AccentStyle.entries) {
            val actual = analystColors(dark, accent)
            for (fill in listOf(actual.material.surface, actual.semantic.disabledContainer,
                actual.material.primaryContainer)) {
                readable(actual.semantic.disabledInk, fill, 3.0)
            }
            readable(actual.material.onPrimaryContainer, actual.material.primaryContainer)
            readable(actual.material.primary, actual.material.surface)
        }
    }
}

package ru.omnicio.app.ui.theme

import android.content.res.Configuration
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Assert.fail
import org.junit.Test

class ApplicationThemeModeTest {
    private class Source : SystemThemeSource {
        var currentValue: SystemThemeObservation = SystemThemeObservation.Known(false)
        var callback: ((SystemThemeObservation) -> Unit)? = null
        val calls = mutableListOf<String>()
        var registrationFailure = false
        var readFailure = false
        var unexpectedReadFailure = false
        var cleanupFailure = false

        override fun current(): SystemThemeObservation {
            calls += "current"
            if (readFailure) throw SystemThemePlatformFailure(SystemThemeUnavailableReason.DISPLAY_UNAVAILABLE)
            if (unexpectedReadFailure) throw IllegalStateException("Synthetic programming failure")
            return currentValue
        }

        override fun register(listener: (SystemThemeObservation) -> Unit) {
            calls += "register"
            callback = listener
            if (registrationFailure) throw SystemThemePlatformFailure(SystemThemeUnavailableReason.CONTEXT_UNAVAILABLE)
        }

        override fun unregister(listener: (SystemThemeObservation) -> Unit) {
            calls += "unregister"
            assertTrue(callback === listener)
            if (cleanupFailure) throw SystemThemePlatformFailure(SystemThemeUnavailableReason.DISPLAY_UNAVAILABLE)
        }
    }

    @Test fun applicationPolicyUsesThePlatformApplicationContract() {
        assertEquals(2, applicationNightMode(ThemeMode.LIGHT))
        assertEquals(2, applicationNightMode(ThemeMode.DARK))
        assertEquals(2, applicationNightMode(ThemeMode.SYSTEM))
    }

    @Test fun undefinedNightBitsAreUnknownRatherThanInventedDaylight() {
        assertEquals(SystemThemeObservation.Known(false), systemThemeObservation(Configuration.UI_MODE_TYPE_NORMAL or Configuration.UI_MODE_NIGHT_NO))
        assertEquals(SystemThemeObservation.Known(true), systemThemeObservation(Configuration.UI_MODE_TYPE_DESK or Configuration.UI_MODE_NIGHT_YES))
        assertEquals(SystemThemeObservation.Unknown(SystemThemeUnavailableReason.UNDEFINED_CONFIGURATION),
            systemThemeObservation(Configuration.UI_MODE_TYPE_NORMAL))
        assertEquals(SystemThemeObservation.Unknown(SystemThemeUnavailableReason.UNDEFINED_CONFIGURATION),
            systemThemeObservation(Configuration.UI_MODE_NIGHT_MASK))
    }

    @Test fun sessionSubscribesBeforeReadingAndPublishesRealSourceChanges() {
        val source = Source()
        val observed = mutableListOf<SystemThemeObservation>()
        val session = SystemThemeObservationSession(source) { observed += it }
        assertEquals(listOf("register", "current"), source.calls)
        assertEquals(listOf(SystemThemeObservation.Known(false)), observed)
        source.callback!!(SystemThemeObservation.Known(true))
        source.callback!!(SystemThemeObservation.Unknown(SystemThemeUnavailableReason.UNDEFINED_CONFIGURATION))
        assertEquals(listOf(SystemThemeObservation.Known(false), SystemThemeObservation.Known(true),
            SystemThemeObservation.Unknown(SystemThemeUnavailableReason.UNDEFINED_CONFIGURATION)), observed)
        session.close()
    }

    @Test fun queuedCallbacksCannotChangeTheUiAfterDisposal() {
        val source = Source()
        val observed = mutableListOf<SystemThemeObservation>()
        val session = SystemThemeObservationSession(source) { observed += it }
        val queued = source.callback!!
        session.close()
        session.close()
        queued(SystemThemeObservation.Known(true))
        assertEquals(listOf(SystemThemeObservation.Known(false)), observed)
        assertEquals(listOf("register", "current", "unregister"), source.calls)
    }

    @Test fun partialRegistrationFailureIsExplicitAndStillUnregisters() {
        val source = Source().apply { registrationFailure = true }
        val observed = mutableListOf<SystemThemeObservation>()
        val session = SystemThemeObservationSession(source) { observed += it }
        source.callback!!(SystemThemeObservation.Known(true))
        session.close()
        assertEquals(listOf(SystemThemeObservation.Unknown(SystemThemeUnavailableReason.CONTEXT_UNAVAILABLE)), observed)
        assertEquals(listOf("register", "unregister"), source.calls)
    }

    @Test fun removedDisplayDuringInitialReadCannotRetainAPreviousKnownValue() {
        val source = Source().apply { readFailure = true }
        val observed = mutableListOf<SystemThemeObservation>()
        val session = SystemThemeObservationSession(source) { observed += it }
        source.callback!!(SystemThemeObservation.Known(true))
        session.close()
        assertEquals(listOf(SystemThemeObservation.Unknown(SystemThemeUnavailableReason.DISPLAY_UNAVAILABLE)), observed)
        assertEquals(listOf("register", "current", "unregister"), source.calls)
    }

    @Test fun removedContextDuringCleanupDoesNotRearmItsCallback() {
        val source = Source().apply { cleanupFailure = true }
        val observed = mutableListOf<SystemThemeObservation>()
        val session = SystemThemeObservationSession(source) { observed += it }
        session.close()
        source.callback!!(SystemThemeObservation.Known(true))
        session.close()
        assertEquals(listOf(SystemThemeObservation.Known(false)), observed)
        assertEquals(listOf("register", "current", "unregister"), source.calls)
    }

    @Test fun unexpectedFailuresPropagateAfterReleasingTheRegistration() {
        val source = Source().apply { unexpectedReadFailure = true }
        val observed = mutableListOf<SystemThemeObservation>()
        try {
            SystemThemeObservationSession(source) { observed += it }
            fail("Unexpected programming failure was swallowed")
        } catch (expected: IllegalStateException) {
            assertEquals("Synthetic programming failure", expected.message)
        }
        source.callback!!(SystemThemeObservation.Known(true))
        assertTrue(observed.isEmpty())
        assertEquals(listOf("register", "current", "unregister"), source.calls)
    }
}

